import sys, json, os, subprocess
env = dict(os.environ, SYNECDOCHE_SITE='/workspace/site', LD_LIBRARY_PATH='/workspace/native', PYTHONPATH='/workspace/site')

def rel(motifs, copies=2, width=3, eps=(1,1000), ratio_num=1):
    disc=[]
    for motif in motifs:
        for _ in range(copies):
            disc.append({'class':0,'values':[0]*24+list(motif)+[0]*24,
                         'activation':[0]*24+[100]*len(motif)+[0]*24})
    validation=[{'class':0,'values':[m for motif in motifs for m in motif][:128]}]
    return {'id':'m','classes':1,'width':width,'eps':list(eps),'ratio':[ratio_num,len(motifs)],
            'threshold':[0,1],'mode':'range','packet_limit':200000,'idle_us':10**12,
            'discovery':disc,'train':[{'class':0,'values':[1515,1516,1517]}],
            'validation':validation}

def run(release, packets, blocks=None):
    if blocks is None:
        blocks=[[['install','m'],['open','f']]+[['packet','f',i,0,p] for i,p in enumerate(packets)]+[['close','f']]]
    req={'capacity':{'range':100,'exact':100},'releases':[release],'blocks':blocks}
    p=subprocess.run([sys.executable,'/workspace/submission/run.py'],input=json.dumps(req,separators=(',',':')).encode(),capture_output=True,env=env)
    return json.loads(p.stdout)

# earliest match wins over a future higher-priority match
r = rel([[1515,1516],[1515,1516,1517]])
out = run(r, [1,2,3])
print('earliest:', out['decisions'], 'priority', out['catalog'][0]['priority'])

# same-packet tie: higher priority (larger id here) must win
r = rel([[1515,1516],[1515,1518]])
out = run(r, [1,4])
print('two clusters:', out['catalog'][0]['priority'], [ (c['id'],c['score']) for c in out['catalog'][0]['clusters']], out['decisions'])
PYEOF
